//! Embeds `assets/tend.ico` (generated by `scripts/brand/tend_icons.py`) as
//! the icon of `tend-app.exe`, so Explorer, Start and a pinned taskbar
//! button show the Tend icon. Only for the MSVC toolchain, the supported one
//! on Windows (`docs/WINDOWS.md`); other targets build without it.

#[path = "src/icon_res.rs"]
mod icon_res;

use std::path::PathBuf;

fn main() {
    println!("cargo:rerun-if-changed=assets/tend.ico");
    println!("cargo:rerun-if-changed=src/icon_res.rs");
    let windows = std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows");
    let msvc = std::env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc");
    if !(windows && msvc) {
        return;
    }
    let ico = std::fs::read("assets/tend.ico").expect("crates/tend-app/assets/tend.ico");
    let res = icon_res::res_from_ico(&ico).expect("assets/tend.ico is a well-formed icon file");
    let out =
        PathBuf::from(std::env::var_os("OUT_DIR").expect("OUT_DIR")).join("tend-app-icon.res");
    std::fs::write(&out, res).expect("write the icon resource");
    // link.exe and lld-link take a compiled resource file as an input.
    println!("cargo:rustc-link-arg-bins={}", out.display());
}
